#include <bits/stdc++.h>
using namespace std;
int main() {
	cin.tie(0);
	int t,n;
	cin>>t;
	while(t--) {
		cin>>n;
		long long x,r=0;
		vector<long long> v;
		for(int i=0;i<n;i++) {
			cin>>x;
			r+=x;
			if(x%2) v.push_back(x);
		} if(v.empty()) {cout<<0<<'\n';continue;}
		sort(v.begin(),v.end());
		for(int i=0;i<v.size()/2;i++) r-=v[i];
		cout<<r<<'\n';
	}
}

